<div class="tray" id="tray"></div>

<script>
/* ════════════════════════════════════════
   TOOLTIP ENGINE — body-anchored, overflow-safe
════════════════════════════════════════ */
(function(){
  const tt = document.getElementById('ktooltip');
  let tid;
  function show(el){
    const text = el.getAttribute('data-tip');
    if(!text) return;
    clearTimeout(tid);
    tt.textContent = text;
    tt.classList.add('vis');
    move(el);
  }
  function move(el){
    const r = el.getBoundingClientRect();
    const tw = tt.offsetWidth || 200;
    const th = tt.offsetHeight || 38;
    let left = r.left + r.width/2 - tw/2;
    let top  = r.top - th - 10;
    // flip below if not enough room above
    if(top < 6){ top = r.bottom + 10; }
    // clamp horizontally
    left = Math.max(8, Math.min(left, window.innerWidth - tw - 8));
    tt.style.left = left + 'px';
    tt.style.top  = top  + 'px';
  }
  function hide(){
    tid = setTimeout(() => tt.classList.remove('vis'), 80);
  }
  let current = null;

  document.addEventListener('mouseover', e => {
    const el = e.target.closest('[data-tip]');
    if(el === current) return;           // même élément, rien à faire
    if(current) hide();                  // on quitte le précédent
    current = el;
    if(el) show(el);
  });

  document.addEventListener('mousemove', e => {
    if(current && tt.classList.contains('vis')) move(current);
  });

  document.addEventListener('mouseout', e => {
    // masquer seulement si on quitte vraiment l'élément courant (pas un enfant)
    if(current && !current.contains(e.relatedTarget)) {
      hide();
      current = null;
    }
  });

  document.addEventListener('click', () => { hide(); current = null; });
})();

/* ════════════════════════════════════════
   CONFIG
════════════════════════════════════════ */
const SID = '1KAzVswQSZKvjimqSEG63Fg1zbeJrSMk8WxMkAm6Uq24';
const POLL_MS = 3000; // 3-second polling — near real-time

/* ── Photos de profil — associer pseudo (sans [X]) → URL image ──
   Exemple : 'Shulio': 'https://exemple.com/photo.jpg'
   Laisser vide = icône par défaut                               */
// Avatar store — persisté en localStorage
const OGRINE_ICON = 'data:image/png;base64,';
const PHOTOS = {};
try {
  Object.keys(localStorage)
    .filter(k => k.startsWith('kav:'))
    .forEach(k => { PHOTOS[k.slice(4)] = localStorage.getItem(k); });
} catch(e) {}
function setPhoto(name, val) {
  if (val) PHOTOS[name] = val; else delete PHOTOS[name];
  try { val ? localStorage.setItem('kav:'+name, val) : localStorage.removeItem('kav:'+name); } catch(e) {}
}

const TABS = [
  {key:'shulio',   name:'Shulio',       icon:'💰'},
  {key:'staff',    name:'Staff',        icon:'🧑‍💼'},
  {key:'absence',  name:'Absence',      icon:'🏖️'},
  {key:'suivis',   name:'Suivis évent', icon:'🎯'},
  {key:'ancien',   name:'Ancien Anim',  icon:'🗃️'},
  {key:'document', name:'Document',     icon:'📝'},
  {key:'mekinu',   name:'Mekinu',       icon:'🗡️'},
  {key:'silent',   name:'Silent',       icon:'🤫'},
  {key:'date0326', name:'03/26',        icon:'⏳'},
];

const NAV = {
  dashboard:'DASHBOARD',analytics:'ANALYTIQUES',activity:'ACTIVITÉ LIVE',
  shulio:'SHULIO',staff:'STAFF',absence:'ABSENCE',suivis:'SUIVIS ÉVENT',
  ancien:'ANCIEN ANIM',document:'DOCUMENT',mekinu:'MEKINU',silent:'SILENT',date0326:'03/26',
  archives:'HISTORIQUE'
};

/* ════════════════════════════════════════
   STATE
════════════════════════════════════════ */
const D = {};       // key → {headers, rows}
const FP = {};      // key → fingerprint
const FEED = [];    // activity feed entries
let cur = 'dashboard';
let pollTimer = null;
let countTimer = null;
let countDown = POLL_MS / 1000;
let ogTotal = null;
let firstLoad = true;

/* ════════════════════════════════════════
   JSONP LOADER — no CORS, works from file://
   Smart: only fetches one tab at a time to 
   stay within Google's rate limits at 3s
════════════════════════════════════════ */
let tabQueue = [...TABS];
let queueIdx = 0;

function fetchTab(key, name) {
  return new Promise((resolve, reject) => {
    document.getElementById('_sc_' + key)?.remove();
    const cb = '__K' + key + Date.now();
    window[cb] = obj => {
      delete window[cb];
      document.getElementById('_sc_' + key)?.remove();
      resolve(obj);
    };
    const t = setTimeout(() => {
      delete window[cb];
      document.getElementById('_sc_' + key)?.remove();
      reject(new Error('timeout: ' + name));
    }, 8000);
    const prev = window[cb];
    window[cb] = obj => { clearTimeout(t); prev(obj); };
    const sc = document.createElement('script');
    sc.id = '_sc_' + key;
    sc.onerror = () => { delete window[cb]; sc.remove(); reject(new Error('load error: ' + name)); };
    sc.src = `https://docs.google.com/spreadsheets/d/${SID}/gviz/tq?tqx=out:json;responseHandler:${cb}&sheet=${encodeURIComponent(name)}&t=${Date.now()}`;
    document.head.appendChild(sc);
  });
}

function parseGviz(obj) {
  if (!obj || obj.status === 'error') throw new Error('gviz error');
  const tbl = obj.table || {};
  const headers = (tbl.cols || []).map(c => (c.label || c.id || '').trim());
  const rows = (tbl.rows || [])
    .map(r => (r.c || []).map(cell => {
      if (!cell || cell.v == null) return '';
      return cell.f != null ? String(cell.f) : String(cell.v);
    }))
    .filter(r => r.some(v => v.trim()));
  return { headers, rows };
}

function fp(d) {
  if (!d || !d.rows.length) return '';
  // Hash ALL rows so any modification anywhere is detected
  return d.rows.length + '|' + d.rows.map(r => r.join('~')).join('||');
}

/* ════════════════════════════════════════
   POLL STRATEGY:
   - Toutes les 3s, fetch TOUS les onglets en parallèle (Promise.allSettled)
   - Détection des changements sur chaque onglet simultanément
════════════════════════════════════════ */
async function pollAll() {
  setDot('busy', 'Sync…');
  const results = await Promise.allSettled(
    TABS.map(tab => fetchTab(tab.key, tab.name).then(raw => {
      const d = parseGviz(raw);
      if (tab.key === 'absence' && d.headers.every(h => /^[A-Z]$/.test(h.trim()))) {
        d.headers = ['Date de début','Date de fin','Membre concerné','Remplis par','Raison','En cours ?'];
        if (d.rows.length && d.rows[0].some(c => /date de début|membre|remplis/i.test(String(c)))) {
          d.rows = d.rows.slice(1);
        }
      }
      return { tab, d };
    }))
  );

  let anyChange = false;

  for (const res of results) {
    if (res.status !== 'fulfilled') {
      console.warn('[Karashi poll]', res.reason?.message);
      continue;
    }
    const { tab, d } = res.value;
    const newFp = fp(d);
    const changed = !firstLoad && FP[tab.key] && FP[tab.key] !== newFp;

    if (changed) {
      anyChange = true;
      const prevLen = D[tab.key] ? D[tab.key].rows.length : 0;

      if (d.rows.length > prevLen) {
        const newRows = d.rows.slice(prevLen);
        newRows.forEach(row => {
          FEED.unshift({ type:'add', src: tab.name, icon: tab.icon, who: extractWho(d.headers, row), cells: row, ts: new Date(), isNew: true });
        });
        FEED.splice(60);
        const badge = document.getElementById('nb-' + tab.key);
        if (badge) { badge.classList.add('updated'); setTimeout(() => badge.classList.remove('updated'), 1200); }
        showUpd(tab.name, d.rows.length - prevLen);
        if (isOgTab(tab.key, d)) toast('◎', 'Ogrines mis à jour · ' + tab.name, 'og');
        else toast('✚', tab.name + ' · ' + (d.rows.length - prevLen) + ' nouvelle(s) ligne(s)', 'live');

      } else if (d.rows.length < D[tab.key].rows.length) {
        const prevRows = D[tab.key].rows;
        FEED.unshift({ type:'del', src: tab.name, icon: tab.icon, who: extractWho(d.headers, prevRows[prevRows.length-1]||[]), cells: ['(ligne supprimée)'], ts: new Date(), isNew: true });
        FEED.splice(60);
        toast('✕', tab.name + ' · Ligne supprimée');
      } else {
        const prevRows = D[tab.key].rows;
        let modRow = d.rows[d.rows.length - 1];
        for (let ri = 0; ri < d.rows.length; ri++) {
          if ((d.rows[ri] || []).join('~') !== (prevRows[ri] || []).join('~')) { modRow = d.rows[ri]; break; }
        }
        FEED.unshift({ type:'mod', src: tab.name, icon: tab.icon, who: extractWho(d.headers, modRow), cells: modRow, ts: new Date(), isNew: true });
        FEED.splice(60);
        toast('✎', tab.name + ' · Données modifiées');
      }
    }

    FP[tab.key] = newFp;
    D[tab.key] = d;
    if (tab.key === 'staff') mergeLocalStaff();
    else if (tab.key === 'absence') mergeLocalAbsence();
    else if (tab.key === 'suivis') mergeLocalSuivis();
    const el = document.getElementById('nb-' + tab.key);
    if (el) el.textContent = tab.key === 'absence' ? countAbsences(d) : tab.key === 'suivis' ? countSuivis(d) : tab.key === 'ancien' ? countAncien(d) : countReal(d);
  }

  if (anyChange || firstLoad) {
    ogTotal = null; recomputeOg(); updateStats(); renderCur();
    if (cur === 'activity') renderActivity();
  }

  setDot('ok', loadedCount() + '/' + TABS.length + ' onglets');
}

function loadedCount() { return TABS.filter(t => D[t.key]?.rows.length > 0).length; }
function isOgTab(key, d) { return d.headers.some(h => /ogrine/i.test(h)); }

/* Premier chargement : même logique, juste avec firstLoad=true */
async function fullLoad() {
  setDot('busy', 'Chargement initial…');
  showErr(false);
  ogTotal = null;
  await pollAll();
  firstLoad = false;
  const ok = loadedCount();
  if (ok > 0) {
    const ts = new Date().toLocaleTimeString('fr-FR', {hour:'2-digit',minute:'2-digit',second:'2-digit'});
    document.getElementById('ts-chip').innerHTML = 'Chargé <span class="ts-chip-time">' + ts + '</span>';
    toast('✓', ok + ' onglet' + (ok > 1 ? 's chargés' : ' chargé'));
  } else {
    setDot('err', 'Connexion impossible');
    showErr(true);
  }
}

function manualRefresh() {
  stopPoll();
  ogTotal = null;
  firstLoad = false;
  fullLoad().then(startPoll);
}

/* ════════════════════════════════════════
   COUNTDOWN + POLL CYCLE
════════════════════════════════════════ */
const CIRCUMFERENCE = 2 * Math.PI * 8; // r=8

function startPoll() {
  stopPoll();
  countDown = POLL_MS / 1000;
  updateRing(countDown);

  countTimer = setInterval(() => {
    countDown -= 0.1;
    if (countDown < 0) countDown = POLL_MS / 1000;
    updateRing(Math.max(countDown, 0));
    const s = Math.ceil(countDown);
    document.getElementById('poll-secs').textContent = s;
    document.getElementById('tb-secs').textContent = s;
  }, 100);

  pollTimer = setInterval(async () => {
    await pollAll();
    const ts = new Date().toLocaleTimeString('fr-FR', {hour:'2-digit',minute:'2-digit',second:'2-digit'});
    document.getElementById('ts-chip').innerHTML = 'Sync <span class="ts-chip-time">' + ts + '</span>';
    countDown = POLL_MS / 1000;
  }, POLL_MS);
}

function stopPoll() { clearInterval(pollTimer); clearInterval(countTimer); }

function updateRing(remaining) {
  const el = document.getElementById('ring-fill');
  if (!el) return;
  const pct = remaining / (POLL_MS / 1000);
  el.style.strokeDashoffset = CIRCUMFERENCE * (1 - pct);
}

/* ════════════════════════════════════════
   OGRINES
════════════════════════════════════════ */
function recomputeOg() {
  ogTotal = null;
  const d = D['shulio'];
  if (!d) return;

  // 1. Colonne dont le header contient "ogrine"
  const hi = d.headers.findIndex(h => /ogrine/i.test(h));
  if (hi >= 0) {
    let s = 0, found = false;
    d.rows.forEach(r => { const n = pn(r[hi]); if (!isNaN(n) && n > 0) { s += n; found = true; } });
    if (found) { ogTotal = s; return; }
  }

  // 2. Cellule dont le contenu contient "ogrine" → valeur dans la même cellule ou la suivante
  for (let ri = 0; ri < d.rows.length; ri++) {
    for (let ci = 0; ci < (d.rows[ri] || []).length; ci++) {
      const cell = String(d.rows[ri][ci] || '');
      if (/ogrine/i.test(cell)) {
        const n = pn(cell.replace(/[^\d\s,.]/g, ''));
        if (!isNaN(n) && n > 0) { ogTotal = n; return; }
        // Valeur à droite
        const right = (d.rows[ri] || [])[ci + 1];
        if (right) { const n2 = pn(right); if (!isNaN(n2) && n2 > 0) { ogTotal = n2; return; } }
        // Valeur en dessous
        const below = (d.rows[ri + 1] || [])[ci];
        if (below) { const n3 = pn(below); if (!isNaN(n3) && n3 > 0) { ogTotal = n3; return; } }
      }
    }
  }

  // 3. Fallback : plus grande valeur numérique dans tout le tableau Shulio
  let best = null;
  d.rows.forEach(r => r.forEach(cell => {
    const n = pn(cell);
    if (!isNaN(n) && n > 0 && (best === null || n > best)) best = n;
  }));
  if (best !== null) ogTotal = best;
}

function pn(s) { return parseFloat(String(s || '').replace(/\s/g, '').replace(',', '.')); }
function fmt(n) { return Number(n).toLocaleString('fr-FR'); }

/* ════════════════════════════════════════
   STATS
════════════════════════════════════════ */
function updateStats() {
  // countReal() utilisé pour tous les onglets — seules les lignes vraiment remplies comptent
  setText('s-staff', countNamed(D['staff']));
  setText('s-abs',   countAbsences(D['absence']));
  setText('s-ev',    countSuivis(D['suivis']));
  setText('s-anc',   countAncien(D['ancien']));
  setText('s-tabs',  loadedCount());

  const hero = document.getElementById('og-hero');
  if (ogTotal != null && ogTotal > 0) {
    document.getElementById('og-num').textContent = fmt(Math.round(ogTotal));
    const metaEl = document.getElementById('og-meta');
    if (metaEl) metaEl.textContent = 'Dernière sync · ' + new Date().toLocaleTimeString('fr-FR', {hour:'2-digit',minute:'2-digit',second:'2-digit'});
    hero.style.display = 'flex';
    // Mini stats
    const mo = ogThisMonth();
    const moEl = document.getElementById('og-mo-mini');
    if (moEl) moEl.textContent = mo != null ? fmt(Math.round(mo)) : '—';
    const stEl = document.getElementById('og-staff-mini');
    if (stEl) stEl.textContent = countNamed(D['staff']) || '—';
    const abEl = document.getElementById('og-abs-mini');
    if (abEl) abEl.textContent = countAbsences(D['absence']) || '—';
    // Spawn particles once
    const pc = document.getElementById('og-particles');
    if (pc && !pc.dataset.spawned) {
      pc.dataset.spawned = '1';
      for (let i = 0; i < 180; i++) {
        const p = document.createElement('div');
        p.className = 'og-p';
        p.style.left = Math.random()*100 + '%';
        p.style.bottom = (Math.random()*100) + '%';
        p.style.setProperty('--dur', (2 + Math.random()*7) + 's');
        p.style.setProperty('--delay', (Math.random()*10) + 's');
        p.style.setProperty('--dx', (Math.random()*50-25) + 'px');
        const sz = (0.8 + Math.random()*4);
        p.style.width = sz + 'px';
        p.style.height = sz + 'px';
        p.style.opacity = (0.2 + Math.random()*0.8).toString();
        pc.appendChild(p);
      }
    }
  } else hero.style.display = 'none';

  const mo = ogThisMonth();
  setText('s-mo', mo != null ? fmt(Math.round(mo)) : null);
}

function setText(id, val) {
  const el = document.getElementById(id);
  if (el) el.textContent = val != null ? val : '—';
}

/* ── countReal: ne compte que les lignes avec au moins une cellule
   vraiment remplie (ni vide, ni tiret seul, ni null, ni 0 seul) ── */
function countReal(d) {
  if (!d || !d.rows.length) return 0;
  return d.rows.filter(row =>
    row.some(cell => {
      const v = String(cell ?? '').trim();
      return v.length > 0
        && v !== '—' && v !== '-' && v !== '--' && v !== '–'
        && v !== 'null' && v !== 'undefined' && v !== 'false'
        && v !== '0' && v !== 'N/A' && v !== 'n/a' && v !== '/';
    })
  ).length;
}

/* ── countNamed: compte uniquement les lignes avec un nom rempli ── */
function countNamed(d) {
  if (!d || !d.rows.length) return 0;
  const nameIdxs = d.headers.map((h,i) => isNameH(h) ? i : -1).filter(i => i >= 0);
  if (nameIdxs.length === 0) return countReal(d);
  return d.rows.filter(row => nameIdxs.some(i => isRealVal(row[i]))).length;
}

/* ── countAncien: gère le sheet avec ligne titre fusionnée en haut.
   Gviz lit cette ligne comme headers → les vrais headers ("Horodateur",
   "Nom du Staff"…) atterrissent dans d.rows comme 1ère ligne de données.
   On l'ignore et on compte les lignes suivantes non-vides. ── */
function countAncien(d) {
  if (!d || !d.rows.length) return 0;
  return d.rows.filter(row => {
    // Ignorer la ligne qui contient les vrais en-têtes de colonnes
    if (row.some(cell => /horodateur|nom du staff/i.test(String(cell)))) return false;
    // Compter les lignes avec au moins une cellule remplie
    return row.some(cell => isRealVal(cell));
  }).length;
}

/* ── countSuivis: ne compte que les lignes du suivi évent
   qui ont AU MOINS une date ET un nom d'événement (ou animateur) remplis. ── */
function countSuivis(d) {
  if (!d || !d.rows.length) return 0;
  const dateIdxs = d.headers.map((h,i) => isDateH(h) ? i : -1).filter(i => i >= 0);
  const nameIdxs = d.headers.map((h,i) => isNameH(h) ? i : -1).filter(i => i >= 0);
  const fallbackIdx = d.headers.findIndex((h,i) => !isDateH(h) && !isOgH(h) && h.trim());

  return d.rows.filter(row => {
    const hasDate = dateIdxs.some(i => isRealVal(row[i]));
    const nameCheck = nameIdxs.length > 0
      ? nameIdxs.some(i => isRealVal(row[i]))
      : (fallbackIdx >= 0 ? isRealVal(row[fallbackIdx]) : true);
    return hasDate && nameCheck;
  }).length;
}


/* ── isRealVal: cellule considérée comme remplie ── */
function isRealVal(v) {
  const s = String(v ?? '').trim();
  return s.length > 0
    && s !== '—' && s !== '-' && s !== '--' && s !== '–'
    && s !== 'null' && s !== 'undefined' && s !== 'false'
    && s !== '0' && s !== 'N/A' && s !== 'n/a' && s !== '/';
}

/* ── countAbsences: ne compte que les lignes de l'onglet Absence
   qui ont AU MOINS une date ET un nom/pseudo remplis.
   Cela évite de compter les lignes vides ou les entrées partielles. ── */
function countAbsences(d) {
  if (!d || !d.rows.length) return 0;
  // Index des colonnes dates et noms
  const dateIdxs = d.headers.map((h,i) => isDateH(h) ? i : -1).filter(i => i >= 0);
  const nameIdxs = d.headers.map((h,i) => isNameH(h) ? i : -1).filter(i => i >= 0);
  // Fallback : si pas de colonne nom détectée, prendre la 1ère colonne non-date
  const fallbackIdx = d.headers.findIndex((h,i) => !isDateH(h) && !isOgH(h) && h.trim());

  return d.rows.filter(row => {
    const hasDate = dateIdxs.some(i => isRealVal(row[i]));
    const nameCheck = nameIdxs.length > 0
      ? nameIdxs.some(i => isRealVal(row[i]))
      : (fallbackIdx >= 0 ? isRealVal(row[fallbackIdx]) : true);
    return hasDate && nameCheck;
  }).length;
}


/* ════════════════════════════════════════
   DATE UTILS
════════════════════════════════════════ */
function toYM(s) {
  if (!s) return null;
  let d = new Date(s);
  if (!isNaN(d) && d.getFullYear() > 2000)
    return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0');
  const m = String(s).match(/(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})/);
  if (m) {
    const [,dd,mm,yy] = m;
    d = new Date(`${yy.length===2?'20'+yy:yy}-${mm.padStart(2,'0')}-${dd.padStart(2,'0')}`);
    if (!isNaN(d) && d.getFullYear() > 2000)
      return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0');
  }
  return null;
}

function moLbl(ym) {
  if (!ym || ym.length !== 7) return ym || '?';
  const [y, m] = ym.split('-');
  const mo = ['Jan','Fév','Mar','Avr','Mai','Jun','Jul','Aoû','Sep','Oct','Nov','Déc'];
  return mo[+m-1] + ' ' + y.slice(2);
}

function nowYM() {
  const n = new Date();
  return n.getFullYear() + '-' + String(n.getMonth()+1).padStart(2,'0');
}

function ogThisMonth() {
  const mo = nowYM();
  for (const tab of TABS) {
    const d = D[tab.key]; if (!d) continue;
    const oi = d.headers.findIndex(h => /ogrine/i.test(h));
    const di = d.headers.findIndex(h => isDateH(h));
    if (oi < 0) continue;
    let s = 0, found = false;
    d.rows.forEach(r => {
      if (di >= 0 && toYM(r[di]) !== mo) return;
      const n = pn(r[oi]); if (!isNaN(n)) { s += n; found = true; }
    });
    if (found) return s;
  }
  return null;
}

/* ════════════════════════════════════════
   ANALYTICS DATA
════════════════════════════════════════ */
function ogByMonth() {
  const m = {};
  for (const tab of TABS) {
    const d = D[tab.key]; if (!d) continue;
    const oi = d.headers.findIndex(h => /ogrine/i.test(h));
    const di = d.headers.findIndex(h => isDateH(h));
    if (oi < 0) continue;
    d.rows.forEach(r => {
      const n = pn(r[oi]); if (isNaN(n) || n <= 0) return;
      const k = (di >= 0 ? toYM(r[di]) : null) || '?';
      m[k] = (m[k]||0) + n;
    });
  }
  return m;
}

function evByMonth() {
  const d = D['suivis']; if (!d) return {};
  const di = d.headers.findIndex(h => isDateH(h));
  const m = {};
  d.rows.forEach(r => { const k = (di >= 0 ? toYM(r[di]) : null) || '?'; m[k] = (m[k]||0)+1; });
  return m;
}

function evCat() {
  const d = D['suivis']; if (!d) return {};
  const ci = d.headers.findIndex(h => /catég|type|kind|sorte/i.test(h));
  const fi = ci >= 0 ? ci : d.headers.findIndex((h,i) => !isDateH(h) && !isOgH(h) && h);
  if (fi < 0) return {};
  const m = {};
  d.rows.forEach(r => { const k = (r[fi]||'Autre').trim()||'Autre'; m[k]=(m[k]||0)+1; });
  return m;
}

function statusDist() {
  const d = D['staff']; if (!d) return {};
  const si = d.headers.findIndex(h => isStatH(h));
  if (si < 0) return {};
  const m = {};
  d.rows.forEach(r => { const k = (r[si]||'Inconnu').trim()||'Inconnu'; m[k]=(m[k]||0)+1; });
  return m;
}

/* ════════════════════════════════════════
   RENDER ANALYTICS
════════════════════════════════════════ */
const COLS = ['var(--t)','var(--mg)','var(--g)','var(--ok)','var(--inf)','var(--pur)','var(--warn)','var(--err)','var(--lv)'];

function barChart(id, data, fmtFn, color) {
  const el = document.getElementById(id); if (!el) return;
  const entries = Object.entries(data).sort((a,b)=>a[0].localeCompare(b[0])).slice(-7);
  if (!entries.length) { el.innerHTML = empty('📭','Pas assez de données','Ajoutez des colonnes de date'); return; }
  const mx = Math.max(...entries.map(e=>e[1]), 1);
  el.innerHTML = entries.map(([k,v]) => {
    const pct = Math.round(v/mx*100);
    const lbl = k.length===7 ? moLbl(k) : k.slice(0,9);
    return `<div class="br-row" data-tip="${esc(k)} : ${fmtFn(v)}">
      <span class="br-lbl">${esc(lbl)}</span>
      <div class="br-track"><div class="br-fill" style="width:${pct}%;background:${color}"></div></div>
      <span class="br-val">${fmtFn(v)}</span>
    </div>`;
  }).join('');
}

function donut(svgId, legId, data) {
  const svg = document.getElementById(svgId), leg = document.getElementById(legId);
  if (!svg || !leg) return;
  const entries = Object.entries(data);
  if (!entries.length) { svg.innerHTML=''; leg.innerHTML='<span style="color:var(--tx2);font-size:14.5px">Aucune donnée</span>'; return; }
  const tot = entries.reduce((s,[,v])=>s+v,0);
  const cx=48, cy=48, R=38, r=22;
  let a=-Math.PI/2, paths='';
  entries.forEach(([k,v],i) => {
    const ang = v/tot*Math.PI*2;
    const x1=cx+R*Math.cos(a),y1=cy+R*Math.sin(a);
    const x2=cx+R*Math.cos(a+ang),y2=cy+R*Math.sin(a+ang);
    const ix1=cx+r*Math.cos(a),iy1=cy+r*Math.sin(a);
    const ix2=cx+r*Math.cos(a+ang),iy2=cy+r*Math.sin(a+ang);
    const lg=ang>Math.PI?1:0, col=COLS[i%COLS.length];
    paths+=`<path d="M${ix1} ${iy1}L${x1} ${y1}A${R} ${R} 0 ${lg} 1 ${x2} ${y2}L${ix2} ${iy2}A${r} ${r} 0 ${lg} 0 ${ix1} ${iy1}Z" fill="${col}" opacity=".85"><title>${esc(k)}: ${v}</title></path>`;
    a+=ang;
  });
  paths+=`<text x="48" y="43" text-anchor="middle" fill="var(--tx0)" font-family="var(--fd)" font-size="16" font-weight="700">${tot}</text>
  <text x="48" y="56" text-anchor="middle" fill="var(--tx2)" font-family="var(--fb)" font-size="11">membres</text>`;
  svg.innerHTML=paths;
  leg.innerHTML=entries.map(([k,v],i)=>
    `<div class="dn-item" data-tip="${esc(k)}: ${v} (${Math.round(v/tot*100)}%)">
      <span class="dn-dot" style="background:${COLS[i%COLS.length]}"></span>
      <span>${esc(k.slice(0,16))}</span>
      <span class="dn-pct">${v} (${Math.round(v/tot*100)}%)</span>
    </div>`
  ).join('');
}

function sparkChart(id, data) {
  const el=document.getElementById(id); if(!el) return;
  const vals=Object.entries(data).sort((a,b)=>a[0].localeCompare(b[0])).slice(-8).map(e=>e[1]);
  if(!vals.length) return;
  const mx=Math.max(...vals,1);
  el.innerHTML=vals.map((v,i)=>{
    const h=Math.round(v/mx*100);
    const c=`hsl(${185+i*12},80%,${38+i*4}%)`;
    return `<div class="spark-b" style="height:${h}%;background:${c}" data-tip="${fmt(Math.round(v))} Ogrines"></div>`;
  }).join('');
}

function renderAnalytics() {
  const t = v => v != null ? fmt(Math.round(v)) : '—';
  document.getElementById('kpi-og').textContent = ogTotal ? t(ogTotal) : '—';
  document.getElementById('kpi-ev').textContent = D['suivis'] != null ? countSuivis(D['suivis']) : '—';
  document.getElementById('kpi-st').textContent = D['staff']  != null ? countNamed(D['staff'])  : '—';
  document.getElementById('kpi-ab').textContent = D['absence']!= null ? countAbsences(D['absence']): '—';

  barChart('ch-og',  ogByMonth(), v => fmt(Math.round(v))+' ◎', 'linear-gradient(90deg,var(--g2),var(--g))');
  barChart('ch-ev',  evByMonth(), v => v+' év.',                'linear-gradient(90deg,#0a1c58,var(--inf))');
  barChart('ch-cat', evCat(),     v => v+' / cat',              'linear-gradient(90deg,var(--lv2),var(--lv))');
  donut('dn-svg','dn-leg', statusDist());
  sparkChart('spark', ogByMonth());

  // Staff comparison
  const staffN = D['staff']?.rows.length || 0;
  const ancienN = countAncien(D['ancien'] || null);
  barChart('ch-staff-comp',
    { 'Staff actifs': staffN, 'Anciens animateurs': ancienN },
    v => v + ' membres',
    'linear-gradient(90deg,#003320,var(--ok))'
  );
}

/* ════════════════════════════════════════
   ACTIVITY FEED
════════════════════════════════════════ */
/* Extract the "who" from a row — looks for name/pseudo column */
function extractWho(headers, row) {
  if (!headers || !row) return null;
  const ni = headers.findIndex(h => isNameH(h));
  if (ni >= 0 && row[ni] && row[ni].trim()) return row[ni].trim();
  // Fallback: first non-empty cell that looks like a name (no digits, short)
  for (let i = 0; i < Math.min(row.length, 4); i++) {
    const v = (row[i] || '').trim();
    if (v && v.length > 1 && v.length < 30 && !/^[\d\s.,]+$/.test(v) && !/ogrine/i.test(v)) return v;
  }
  return null;
}

let actFilter = 'all'; // 'all' | 'add' | 'mod' | 'del'

function renderActivity() {
  const el=document.getElementById('activity-feed'); if(!el) return;

  // Category counts
  const counts = { all: FEED.length, add: FEED.filter(f=>f.type==='add').length, mod: FEED.filter(f=>f.type==='mod').length, del: FEED.filter(f=>f.type==='del').length };

  const TYPE_CFG = {
    add: { lbl:'Ajout',        col:'var(--ok)',  icon:'✚', bg:'rgba(34,204,122,.12)',  bc:'rgba(34,204,122,.35)' },
    mod: { lbl:'Modification', col:'var(--g)',   icon:'✎', bg:'rgba(240,184,48,.12)',  bc:'rgba(240,184,48,.35)' },
    del: { lbl:'Suppression',  col:'var(--err)', icon:'✕', bg:'rgba(240,48,80,.12)',   bc:'rgba(240,48,80,.35)' },
  };

  const filterBar = `<div style="display:flex;gap:7px;flex-wrap:wrap;margin-bottom:12px;align-items:center">
    <span style="font-size:13.5px;letter-spacing:2px;color:var(--tx2);text-transform:uppercase;font-weight:700;margin-right:3px">Filtre :</span>
    ${['all','add','mod','del'].map(f => {
      const cfg = f==='all' ? {lbl:'Tout', col:'var(--t3)', icon:'◈', bg:'rgba(0,200,232,.12)', bc:'var(--b1)'} : TYPE_CFG[f];
      const active = actFilter===f;
      return `<button onclick="actFilter='${f}';renderActivity()"
        style="display:inline-flex;align-items:center;gap:5px;padding:7px 15px;border-radius:20px;font-size:14px;font-weight:700;cursor:pointer;border:1px solid ${active?cfg.bc:'var(--b0)'};background:${active?cfg.bg:'transparent'};color:${active?cfg.col:'var(--tx2)'};font-family:var(--fb);letter-spacing:.5px;transition:all .15s">
        <span>${cfg.icon}</span>${cfg.lbl}<span style="background:${active?cfg.bc:'var(--d5)'};color:${active?cfg.col:'var(--tx2)'};border-radius:20px;padding:2px 9px;font-size:13px;font-family:var(--fm)">${f==='all'?counts.all:counts[f]}</span>
      </button>`;
    }).join('')}
  </div>`;

  const visible = FEED.filter(f => actFilter==='all' || f.type===actFilter).slice(0,40);

  if (!visible.length) {
    el.innerHTML = filterBar + `<div class="empty"><span class="ei">⚡</span>${FEED.length?'Aucune entrée dans cette catégorie':'En attente de nouvelles données…'}<div class="es">${FEED.length?'Changez le filtre pour voir les autres catégories':'Les entrées ajoutées dans le Sheet apparaîtront ici'}</div></div>`;
    return;
  }

  const rows = visible.map((a,i) => {
    const cfg = TYPE_CFG[a.type] || {lbl:'?', col:'var(--t3)', icon:'?', bg:'transparent', bc:'var(--b0)'};
    const preview = a.cells.filter(Boolean).slice(0,5).join(' · ');
    const ts = a.ts.toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit',second:'2-digit'});
    const col = COLS[TABS.findIndex(t=>t.name===a.src)%COLS.length]||'var(--t)';
    const whoStr = a.who ? `<span style="font-size:13.5px;color:${cfg.col};font-weight:700;font-family:var(--fd);letter-spacing:.5px;flex-shrink:0">👤 ${esc(a.who)}</span>` : '';
    return `<div class="fi${i<3&&a.isNew?' fi-new':''}" style="${a.isNew&&i<3?'border-color:'+cfg.bc+';background:'+cfg.bg:''}">
      <span style="display:inline-flex;align-items:center;justify-content:center;width:20px;height:20px;border-radius:6px;background:${cfg.bg};border:1px solid ${cfg.bc};font-size:10px;flex-shrink:0;color:${cfg.col};font-weight:900">${cfg.icon}</span>
      <span class="fi-src" style="color:${col}">${a.icon} ${esc(a.src)}</span>
      ${whoStr}
      <span class="fi-txt" title="${esc(preview)}">${esc(preview||'(nouvelle entrée)')}</span>
      <span class="fi-ts">${ts}</span>
    </div>`;
  }).join('');

  el.innerHTML = filterBar + `<div class="feed">${rows}</div>`;
}

/* ════════════════════════════════════════
   DASHBOARD
════════════════════════════════════════ */
function renderDash() {
  const TAB_COLORS = {
    shulio:   {s:'linear-gradient(90deg,var(--g2),var(--g))',    g:'rgba(240,184,48,.06)',   b:'rgba(240,184,48,.18)',  a:'rgba(240,184,48,.9)'},
    staff:    {s:'linear-gradient(90deg,var(--t2),var(--t))',    g:'rgba(0,200,232,.06)',    b:'rgba(0,200,232,.18)',   a:'rgba(0,200,232,.9)'},
    absence:  {s:'linear-gradient(90deg,#600,var(--err))',       g:'rgba(240,48,80,.06)',    b:'rgba(240,48,80,.18)',   a:'rgba(240,80,100,.9)'},
    suivis:   {s:'linear-gradient(90deg,#0a1c58,var(--inf))',    g:'rgba(68,136,255,.06)',   b:'rgba(68,136,255,.18)',  a:'rgba(100,160,255,.9)'},
    ancien:   {s:'linear-gradient(90deg,#35006a,var(--pur))',    g:'rgba(136,102,255,.06)',  b:'rgba(136,102,255,.18)', a:'rgba(160,120,255,.9)'},
    document: {s:'linear-gradient(90deg,#003320,var(--ok))',     g:'rgba(34,204,122,.06)',   b:'rgba(34,204,122,.18)',  a:'rgba(34,204,122,.9)'},
    mekinu:   {s:'linear-gradient(90deg,var(--lv2),var(--lv))',  g:'rgba(255,85,32,.06)',    b:'rgba(255,85,32,.18)',   a:'rgba(255,120,60,.9)'},
    silent:   {s:'linear-gradient(90deg,#1a1a40,var(--pur))',    g:'rgba(136,102,255,.05)',  b:'rgba(136,102,255,.15)', a:'rgba(136,102,255,.9)'},
    date0326: {s:'linear-gradient(90deg,var(--t2),var(--mg))',   g:'rgba(224,64,200,.06)',   b:'rgba(224,64,200,.18)',  a:'rgba(224,64,200,.9)'},
  };
  let html='';
  for (const tab of TABS) {
    const d=D[tab.key]; if(!d) continue;
    if(tab.key==='shulio') continue;
    const n = tab.key === 'staff' ? countNamed(d) : tab.key === 'absence' ? countAbsences(d) : tab.key === 'suivis' ? countSuivis(d) : tab.key === 'ancien' ? countAncien(d) : countReal(d);
    const col = TAB_COLORS[tab.key] || {s:'linear-gradient(90deg,var(--t2),var(--t))',g:'rgba(0,200,232,.06)',b:'rgba(0,200,232,.18)',a:'rgba(0,200,232,.9)'};
    html+=`
    <div class="dpv-card" style="--dpv-b:${col.b};--dpv-g:${col.g};--dpv-s:${col.s};--dpv-a:${col.a}">
      <div class="dpv-head">
        <div class="dpv-top-bar"></div>
        <div class="dpv-left">
          <span class="dpv-icon">${tab.icon}</span>
          <div class="dpv-txt">
            <div class="dpv-title">${tab.name.toUpperCase()}</div>
            <div class="dpv-underline"></div>
            <div class="dpv-entry-count">${n} entrée${n!==1?'s':''}</div>
          </div>
        </div>
        <div class="dpv-actions">
          ${(tab.key==='staff'||tab.key==='absence'||tab.key==='suivis')?`<button onclick="event.stopPropagation();${tab.key==='staff'?'openStaffModal()':tab.key==='suivis'?'openSuivisModal()':'openAbsenceModal()'}" style="display:inline-flex;align-items:center;justify-content:center;gap:7px;padding:10px 20px 10px 22px;border-radius:22px;cursor:pointer;background:rgba(0,200,232,.08);border:1px solid rgba(0,200,232,.32);color:#7ee8f5;font-family:Oxanium,sans-serif;font-size:13px;letter-spacing:1.8px;text-transform:uppercase;font-weight:700;box-shadow:0 0 12px rgba(0,200,232,.1);transition:all .2s;white-space:nowrap;line-height:1" onmouseover="this.style.background='rgba(0,200,232,.18)';this.style.borderColor='rgba(0,200,232,.55)'" onmouseout="this.style.background='rgba(0,200,232,.08)';this.style.borderColor='rgba(0,200,232,.32)'"><svg width="11" height="11" viewBox="0 0 12 12" fill="none" style="pointer-events:none;flex-shrink:0;display:block"><line x1="6" y1="1" x2="6" y2="11" stroke="currentColor" stroke-width="2" stroke-linecap="round"/><line x1="1" y1="6" x2="11" y2="6" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg> Ajouter</button>`:''}
          <button class="dpv-expand-btn" id="dpv-tog-${tab.key}" onclick="toggleDpvCard('${tab.key}')" title="Déplier / Réduire">
            <span class="dpv-expand-label">TOUT VOIR</span>
            <span class="dpv-expand-arrow">
              <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M6 9L12 15L18 9" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
              </svg>
            </span>
          </button>
        </div>
      </div>
      <div class="dpv-body" id="dpv-body-${tab.key}">${buildTable(d, tab.key, tab.name, {srch:false, max:3, noWrap:true, requireName:true})}</div>
    </div>`;
  }
  if(!html) html=empty('◈','Aucune donnée','Vérifiez les permissions du Sheet');
  document.getElementById('dash-prev').innerHTML=html;
  if(window.twemoji) twemoji.parse(document.getElementById('dash-prev'), {folder:'svg',ext:'.svg'});
  // Reset expanded state — DOM is fully rebuilt, old state is stale
  Object.keys(_dpvExpanded).forEach(k => delete _dpvExpanded[k]);
}

const _dpvExpanded = {}; // track expanded state per tab key

function toggleDpvCard(key) {
  const body = document.getElementById('dpv-body-' + key);
  const btn  = document.getElementById('dpv-tog-' + key);
  if (!body) return;

  _dpvExpanded[key] = !_dpvExpanded[key];
  const expanded = _dpvExpanded[key];
  const d = D[key];

  body.innerHTML = d
    ? buildTable(d, key, TABS.find(t=>t.key===key)?.name||key, {
        srch: expanded, max: expanded ? null : 3, noWrap: !expanded, requireName: false
      })
    : '';

  if (btn) {
    const label = btn.querySelector('.dpv-expand-label');
    const arrow = btn.querySelector('.dpv-expand-arrow');
    if (label) label.textContent = expanded ? 'RÉDUIRE' : 'TOUT VOIR';
    if (arrow) arrow.style.transform = expanded ? 'rotate(180deg)' : 'rotate(0deg)';
    btn.classList.toggle('expanded', expanded);
  }
}

/* ════════════════════════════════════════
   TAB VIEW
════════════════════════════════════════ */
function renderTab(key) {
  const tab=TABS.find(t=>t.key===key); if(!tab) return;
  const el=document.getElementById('c-'+key); if(!el) return;
  const d=D[key];
  const realN = d ? countReal(d) : 0;
  let html=`<div class="sh"><span class="sh-bracket">[</span><span class="sh-dot"></span><h2>${tab.icon} ${tab.name.toUpperCase()}</h2><span class="sh-bracket">]</span><div class="sh-line"></div>
    ${d?`<span class="sh-pill">${realN} ligne${realN!==1?'s':''}</span>`:''}</div>`;
  if (d) {
    // Ogrines sum
    const oi=d.headers.findIndex(h=>isOgH(h));
    if(oi>=0){
      let s=0,found=false;
      d.rows.forEach(r=>{const n=pn(r[oi]);if(!isNaN(n)){s+=n;found=true;}});
      if(found) html+=`<div class="og-hero">
        <div style="width:44px;height:44px;flex-shrink:0;opacity:.85"><svg viewBox="0 0 52 52" fill="none"><circle cx="26" cy="26" r="24" stroke="#f0b830" stroke-width="1.5" fill="none"/><circle cx="26" cy="26" r="18" stroke="#b88020" stroke-width="1" fill="none" opacity=".5"/><path d="M26 8 L29 20 L26 22 L23 20 Z" fill="#ffd060" opacity=".9"/><path d="M26 44 L29 32 L26 30 L23 32 Z" fill="#ffd060" opacity=".7"/><path d="M8 26 L20 23 L22 26 L20 29 Z" fill="#ffd060" opacity=".7"/><path d="M44 26 L32 23 L30 26 L32 29 Z" fill="#ffd060" opacity=".9"/><circle cx="26" cy="26" r="5" fill="#f0b830"/><circle cx="26" cy="26" r="3" fill="#ffe090" opacity=".6"/></svg></div>
        <div><div><span class="og-num" style="font-size:38px">${fmt(Math.round(s))}</span><span class="og-unit">&nbsp;Ogrines</span></div>
        <div class="og-lbl">Total · ${tab.name}</div></div></div>`;
    }
    if(key==='shulio' && oi<0){
      outer:for(let ri=0;ri<Math.min(d.rows.length,10);ri++){
        for(let ci=0;ci<(d.rows[ri]||[]).length;ci++){
          const c=String(d.rows[ri][ci]||'');
          if(/ogrine/i.test(c)&&c.length<70){
            html+=`<div class="og-hero"><div style="font-size:36px;opacity:.8">◎</div>
              <div><div class="og-num" style="font-size:32px">${esc(c)}</div>
              <div class="og-lbl">Valeur principale · Shulio</div></div></div>`;
            break outer;
          }
        }
      }
    }
  }
  html+=buildTable(d, key, tab.name, {srch:true});
  el.innerHTML=html;
}

/* ════════════════════════════════════════
   BUILD TABLE
════════════════════════════════════════ */
let UID=0;
function buildTable(d, key, title, {srch=true,max=null,noWrap=false,requireName=false}={}) {
  if(!d) return `<div class="tc"><div class="tc-bar"><span class="tc-name">${esc(title)}</span></div>${empty('⚠','Onglet indisponible','')}</div>`;
  // Special renderer for suivis tab
  if (key === 'suivis') return buildSuivisTable(d, title, {srch, max, noWrap});
  // Only use real (non-empty) rows
  let realRows = d.rows.filter(row =>
    row.some(cell => {
      const v = String(cell ?? '').trim();
      return v.length > 0 && v !== '—' && v !== '-' && v !== '--' && v !== '–'
        && v !== 'null' && v !== 'undefined' && v !== 'false' && v !== '0'
        && v !== 'N/A' && v !== 'n/a' && v !== '/';
    })
  );
  // For absence tab: require at least a date AND a name/member to be filled
  if (key === 'absence') {
    const dateIdxs = d.headers.map((h,i) => isDateH(h) ? i : -1).filter(i => i >= 0);
    const nameIdxs2 = d.headers.map((h,i) => isNameH(h) ? i : -1).filter(i => i >= 0);
    const fallbackIdx = d.headers.findIndex(h => !isDateH(h) && !isOgH(h) && h.trim());
    realRows = realRows.filter(row => {
      const hasDate = dateIdxs.some(i => isRealVal(row[i]));
      const hasName = nameIdxs2.length > 0
        ? nameIdxs2.some(i => isRealVal(row[i]))
        : (fallbackIdx >= 0 ? isRealVal(row[fallbackIdx]) : true);
      return hasDate && hasName;
    });
  }
  // Always skip rows where the name column is empty (if a name column exists)
  const nameIdxs = d.headers.map((h,i) => isNameH(h) ? i : -1).filter(i => i >= 0);
  if (nameIdxs.length > 0) {
    realRows = realRows.filter(row => nameIdxs.some(i => isRealVal(row[i])));
  }

  // Sort by ID column (numeric) if present
  const idIdx = d.headers.findIndex(h => /^\s*id\s*$/i.test(h));
  if (idIdx >= 0) {
    realRows = [...realRows].sort((a, b) => {
      const na = parseInt(a[idIdx] ?? '', 10);
      const nb = parseInt(b[idIdx] ?? '', 10);
      if (isNaN(na) && isNaN(nb)) return 0;
      if (isNaN(na)) return 1;
      if (isNaN(nb)) return -1;
      return na - nb;
    });
  }
  const _HR={'en cours ?':'Statut','en cours':'Statut'};
  const cols = key === 'absence'
    ? d.headers.map((h,i)=>({h:_HR[h.trim().toLowerCase()]||h.trim(),i})).filter(({h})=>h)
    : d.headers.map((h,i)=>({h:_HR[h.trim().toLowerCase()]||h.trim(),i})).filter(({h,i})=>h&&realRows.some(r=>(r[i]||'').trim()));
  const rows=max?realRows.slice(0,max):realRows;
  const tid='t'+(++UID);
  const thead=cols.length?`<thead><tr>${cols.map(({h})=>`<th>${esc(h)}</th>`).join('')}</tr></thead>`:'';

  // Pre-detect name column index (original headers index)
  const nameColIdx = d.headers.findIndex(h => isNameH(h));

  const tbody=!rows.length
    ?`<tr><td colspan="${Math.max(cols.length,1)}" style="padding:0">${empty('📭','Aucune entrée','')}</td></tr>`
    :rows.map(row=>{
      // Get person name for cross-ref tooltips
      const personName = nameColIdx >= 0 ? stripBrackets((row[nameColIdx]||'').trim()) : '';
      const cells=cols.map(({h,i},ci)=>{
        const v=(row[i]||'').trim();
        let c;
        if(isNameH(h)){
          const clean=stripBrackets(v);
          const photoVal = PHOTOS[clean] || PHOTOS[v] || null;
          let avatarInner;
          if (!photoVal) {
            avatarInner = `<div class="av">${defaultAvatar()}</div>`;
          } else if (photoVal.startsWith('icon:')) {
            const ic = (window.DISCORD_ICONS||[]).find(i=>i.id===photoVal.slice(5));
            avatarInner = `<div class="av" style="padding:5px;box-sizing:border-box;color:var(--t3)">${ic?ic.svg:defaultAvatar()}</div>`;
          } else {
            avatarInner = `<img src="${esc(photoVal)}" class="av-photo" alt="${esc(clean)}" onerror="this.outerHTML='<div class=av>'+defaultAvatar()+'</div>'">`;
          }
          c=`<div class="av-w"><span class="av-wrap" onclick="openAvatarPicker('${esc(clean).replace(/'/g,"\'")}')" title="Changer l'icône">${avatarInner}</span><span class="ct-name">${esc(clean)||'—'}</span></div>`;
        }

        else c=renderCell(isNameH(h)?stripBrackets(v):v, h, personName);
        return `<td${isNameH(h)?" class=\"td-name\"":""}>` + c + `</td>`;
      });
      if (row.__local && cells.length > 0) {
        const lid = row.__lid;
        const edited = [...cells];

        // First cell: badge absolute, name centered via td-name class
        const tdOpen0 = edited[0].match(/^(<td[^>]*>)/)?.[1] || '<td>';
        const inner0 = edited[0].slice(tdOpen0.length, -5);
        const inner0Tagged = inner0.replace('<div class="av-w">', '<div class="av-w"><span class="local-badge-inline"><svg width="8" height="8" viewBox="0 0 24 24" fill="currentColor" style="opacity:.85;pointer-events:none;flex-shrink:0"><path d="M12 2l2.4 7.4H22l-6.2 4.5 2.4 7.4L12 17l-6.2 4.3 2.4-7.4L2 9.4h7.6z"/></svg>Manuel</span>');
        edited[0] = `<td class="td-name" style="vertical-align:middle;text-align:center"><div class="local-name-stack">${inner0Tagged}</div></td>`;

        // All other cells: vertical-align middle only
        for (let ci = 1; ci < edited.length; ci++) {
          edited[ci] = edited[ci].replace(/^<td/, '<td style="vertical-align:middle"');
        }

        // Action buttons replace the last cell content on hover via CSS class
        const lastIdx = edited.length - 1;
        const lastTd  = edited[lastIdx];
        const lastInner = lastTd.replace(/^<td[^>]*>/, '').replace(/<\/td>$/, '');
        edited[lastIdx] = `<td style="vertical-align:middle;position:relative;min-width:220px">
          <div class="lrow-stat">${lastInner}</div>
          <div class="local-actions local-actions-hover" style="position:absolute;inset:0;display:flex;flex-direction:row;gap:6px;align-items:center;justify-content:center;background:rgba(6,13,28,.9);backdrop-filter:blur(4px);border-radius:8px">
            <button class="local-btn local-btn-edit" data-lid="${lid}" data-src="${key}" data-action="edit">
              <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="pointer-events:none"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>Modifier
            </button>
            <button class="local-btn local-btn-del" data-lid="${lid}" data-src="${key}" data-action="delete">
              <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="pointer-events:none"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/><path d="M9 6V4h6v2"/></svg>Supprimer
            </button>
          </div>
        </td>`;

        return `<tr class="local-staff-row">${edited.join('')}</tr>`;
      }
      return `<tr>${cells.join('')}</tr>`;
    }).join('');
  const n = realRows.length;
  const more=(max&&n>max)?`<div class="more">+${n-max} ligne${n-max>1?'s':''} — <a onclick="goTo('${key}')">Tout voir</a></div>`:'';
  const search=srch?`<input type="text" class="tc-srch" placeholder="🔍 Filtrer…" oninput="filterTbl('${tid}',this.value)">`:'';
  if (noWrap) {
    return `<div style="overflow-x:auto"><table class="dt${key==='absence'?' absence-table':''}">${thead}<tbody id="${tid}">${tbody}</tbody></table></div>${more}`;
  }
  return `<div class="tc">
    <div class="tc-bar">
      <span class="tc-name">${esc(title)}</span>
      <span class="tc-cnt">${n} ligne${n!==1?'s':''}</span>
      ${search}
    </div>
    <div style="overflow-x:auto"><table class="dt${key==='absence'?' absence-table':''}">${thead}<tbody id="${tid}">${tbody}</tbody></table></div>
    ${more}
  </div>`;
}

function filterTbl(id,q){
  const el=document.getElementById(id);if(!el)return;
  const ql=q.toLowerCase();
  el.querySelectorAll('tr').forEach(tr=>{tr.style.display=tr.textContent.toLowerCase().includes(ql)?'':'none';});
}

/* ════════════════════════════════════════
   SUIVIS ÉVENT — rendu spécialisé
════════════════════════════════════════ */
function buildSuivisTable(d, title, {srch=true, max=null, noWrap=false}={}) {
  const H = d.headers;

  // ── Column detection
  const iHoro    = findCol(H, 'horodateur', 'timestamp', 'soumis');
  const iDate    = iHoro >= 0 ? iHoro : findCol(H, 'date', 'quand');
  const iAnim    = findCol(H, /^animation$/i);           // à masquer
  const iMembre  = findCol(H, 'membre', 'concerné');
  const iRempli  = findCol(H, 'remplis');
  const iEvent   = findCol(H, /nom.+v.+nement/i, /evenement/i, /event/i);
  const iRecomp  = findCol(H, 'récompense', 'recompense', 'dotation');
  const iPartic  = findCol(H, 'participant', 'joueur', 'nb');
  const iGagnant = findCol(H, 'gagnant', 'winner');
  const iJ       = findCol(H, /^\s*j\s*$/i, 'statut', 'status');  // à masquer

  const HIDDEN = new Set([iAnim, iJ].filter(i => i >= 0));

  // ── Filter real rows (need an event or membre)
  let rows = d.rows.filter(row => {
    const hasMembre = iMembre >= 0 && (row[iMembre]||'').trim();
    const hasEvent  = iEvent  >= 0 && (row[iEvent] ||'').trim();
    return hasMembre || hasEvent;
  });
  if (max) rows = rows.slice(0, max);

  const tid = 't' + (++UID);

  /* Parse dotation string → sorted array aligned with actual winners */
  function parseDotation(recomp, gagnant, particRaw) {
    const amounts = String(recomp||'').split('/').map(s => parseInt(s.replace(/\D/g,''),10)).filter(n=>!isNaN(n));

    // Raw entries split by /
    const allRaw = String(gagnant||'').split('/').map(s => s.trim()).filter(Boolean);
    const disqSet = [];
    const cleanNames = [];

    for (const raw of allRaw) {
      const pIdx = raw.indexOf('(');
      if (pIdx >= 0) {
        // Name before ( → winner; names inside ( → disqualified
        const before = raw.slice(0, pIdx).trim();
        const inside = raw.slice(pIdx + 1).replace(/\)/g, '').trim();
        if (before) cleanNames.push(before);
        // inside may have multiple names separated by space or comma
        inside.split(/[,\s]+/).map(n => n.replace(/disqualif[^,\s]*/i,'').trim()).filter(Boolean).forEach(n => disqSet.push(n));
      } else if (/disqualif/i.test(raw)) {
        // Standalone disqualified entry — extract just the name
        disqSet.push(raw.replace(/\s*disqualif[^\s]*/i,'').replace(/[()]/g,'').trim());
      } else {
        cleanNames.push(raw);
      }
    }

    const MEDALS  = ['🥇','🥈','🥉'];
    const COLORS  = ['#ffd700','#c0c0c0','#cd7f32'];
    const CLASSES = ['podium-gold','podium-silver','podium-bronze'];
    const GLOWS   = ['rgba(255,215,0,.18)','rgba(192,192,192,.14)','rgba(205,127,50,.14)'];

    const count = cleanNames.length > 0 ? Math.min(cleanNames.length, amounts.length) : amounts.length;
    const entries = amounts.slice(0, count).map((amt, i) => ({amt, name: cleanNames[i]||''}));
    entries.sort((a,b) => b.amt - a.amt);

    // Participant count = declared total - disqualified count (they were IN the event but removed)
    const particNum = parseInt(String(particRaw||'').replace(/\D/g,''), 10);
    const adjPartic = !isNaN(particNum) ? Math.max(0, particNum - disqSet.length) : null;

    return {
      rows: entries.map((e,i) => ({
        medal: MEDALS[i]||'·', color: COLORS[i]||'rgba(255,255,255,.5)',
        cls: CLASSES[i]||'', glow: GLOWS[i]||'transparent', amt: e.amt, name: e.name
      })),
      adjPartic,
      disqNames: disqSet.filter(Boolean)
    };
  }

  /* Format date with optional time */
  function fmtSuivisDate(v) {
    if (!v || v === '—') return '—';
    const s = String(v).trim();
    // Try ISO datetime first (2026-03-01T14:32:00 or 2026-03-01 14:32)
    const dtFull = new Date(s.replace(' ','T'));
    if (!isNaN(dtFull)) {
      const d = capDate(dtFull.toLocaleDateString('fr-FR',{day:'2-digit',month:'short',year:'numeric'}));
      const t = dtFull.toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});
      // Only show time if it's not midnight
      return (t !== '00:00' && t !== '01:00') ? `${d} · ${t}` : d;
    }
    return capDate(fmtShortDate(v));
  }

  const rowsHtml = !rows.length
    ? `<tr><td colspan="5" style="padding:0">${empty('📭','Aucune entrée','')}</td></tr>`
    : rows.map(row => {
        const get = i => i >= 0 ? String(row[i]||'').trim() : '';
        const dateRaw   = get(iDate);
        const membre    = stripBrackets(get(iMembre));
        const rempli    = stripBrackets(get(iRempli));
        const event     = get(iEvent);
        const recomp    = get(iRecomp);
        const partic    = get(iPartic);
        const gagnant   = get(iGagnant);

        const dateStr = fmtSuivisDate(dateRaw);
        const pod     = parseDotation(recomp, gagnant, partic);
        const icon    = animEventIcon(event);
        const theme   = animEventTheme(event);

        const particDisplay = pod.rows.length; // = nombre de gagnants valides sur le podium

        /* Avatar helper for staff names */
        function staffAvatar(name) {
          if (!name) return '';
          const photoVal = PHOTOS[name] || null;
          if (!photoVal) return `<div class="sv-av av">${defaultAvatar()}</div>`;
          if (photoVal.startsWith('icon:')) {
            const ic = (window.DISCORD_ICONS||[]).find(i=>i.id===photoVal.slice(5));
            return `<div class="sv-av av" style="padding:3px;box-sizing:border-box;color:var(--t3)">${ic?ic.svg:defaultAvatar()}</div>`;
          }
          const safe = esc(photoVal).replace(/'/g,'&#39;');
          const safeName = esc(name).replace(/'/g,'&#39;');
          return `<img src="${safe}" class="sv-av av-photo" alt="${safeName}" onerror="this.style.display='none'">`;
        }

        const podiumHtml = pod.rows.length === 0 && !gagnant ? `<span class="sv-dash">—</span>` :
          `<div class="sv-podium">${pod.rows.map(p => `
            <div class="sv-podium-row ${p.cls}" style="--prow-glow:${p.glow}">
              <span class="sv-medal">${p.medal}</span>
              <span class="sv-podium-left"><span class="sv-podium-amt" style="color:${p.color}">${fmt(p.amt)}</span><img src="${window.OGRINE_ICON_CLEAN || OGRINE_ICON}" class="sv-og-icon" alt="Ogrines"></span>
              ${p.name ? `<span class="sv-podium-name">${esc(p.name)}</span>` : ''}
            </div>`).join('')}
            ${pod.disqNames.length > 0 ? `<div class="sv-disq-block">${pod.disqNames.map(n=>`
              <div class="sv-disq-row sv-has-tip" data-tip="Motif : Tricherie durant l'événement">
                <span class="sv-disq-bang">!</span>
                <span class="sv-disq-name">${esc(n)}</span>
                <span class="sv-disq-tag">🚫 DISQUALIFIÉ</span>
              </div>`).join('')}</div>` : ''}
            ${particDisplay > 0 ? `<div class="sv-partic"><div class="sv-partic-inner"><svg class="sv-partic-icon" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="9" cy="7" r="3.5" stroke="currentColor" stroke-width="1.6"/><path d="M2 20c0-4 3.1-6 7-6s7 2 7 6" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/><circle cx="17" cy="8" r="2.5" stroke="currentColor" stroke-width="1.4" opacity=".7"/><path d="M20 19c0-2.5-1.8-4-4-4.5" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" opacity=".7"/></svg><span class="sv-partic-num">${particDisplay}</span><span class="sv-partic-label">participant${particDisplay>1?'s':''}</span></div></div>` : ''}
          </div>`;

        return `<tr class="sv-row">
          <td class="sv-date"><span class="sv-date-val">${esc(dateStr)}</span></td>
          <td class="sv-event-cell"><span class="sv-event" style="--sv-ev-bg:${theme.bg};--sv-ev-border:${theme.border};--sv-ev-color:${theme.color}"><span class="sv-event-icon">${icon}</span><span class="sv-event-name">${esc(event)||'—'}</span></span></td>
          <td class="sv-membre"><span class="sv-name-chip">${staffAvatar(membre)}<span>${esc(membre)||'—'}</span></span></td>
          <td class="sv-rempli"><span class="sv-rempli-val">${staffAvatar(rempli)}<span>${esc(rempli)||'—'}</span></span></td>
          <td class="sv-podium-cell">${podiumHtml}</td>
        </tr>`;
      }).join('');

  const thead = `<thead><tr>
    <th>Date</th>
    <th>Événement</th>
    <th>Réalisé par</th>
    <th>Remplis par</th>
    <th>Podium &amp; Récompenses</th>
  </tr></thead>`;

  const n = rows.length;
  const total = d.rows.filter(r => {
    const hasMembre = iMembre >= 0 && (r[iMembre]||'').trim();
    const hasEvent  = iEvent  >= 0 && (r[iEvent] ||'').trim();
    return hasMembre || hasEvent;
  }).length;
  const more = (max && total > max) ? `<div class="more">+${total-max} ligne${total-max>1?'s':''} — <a onclick="goTo('suivis')">Tout voir</a></div>` : '';
  const search = srch ? `<input type="text" class="tc-srch" placeholder="🔍 Filtrer…" oninput="filterTbl('${tid}',this.value)">` : '';

  if (noWrap) {
    return `<div style="overflow-x:auto"><table class="dt sv-table">${thead}<tbody id="${tid}">${rowsHtml}</tbody></table></div>${more}`;
  }
  return `<div class="tc">
    <div class="tc-bar">
      <span class="tc-name">${esc(title)}</span>
      <span class="tc-cnt">${total} ligne${total!==1?'s':''}</span>
      ${search}
    </div>
    <div style="overflow-x:auto"><table class="dt sv-table">${thead}<tbody id="${tid}">${rowsHtml}</tbody></table></div>
    ${more}
  </div>`;
}

/* ════════════════════════════════════════
   STAT PANEL — infobulle riche
════════════════════════════════════════ */
let _kspTimer = null;
function showStatPanel(key, btn) {
  const panel = document.getElementById('kstat-panel');
  if (!panel) return;
  // toggle
  if (panel.classList.contains('vis') && panel._activeKey === key) {
    closeStatPanel(); return;
  }
  panel._activeKey = key;
  const d = D[key];
  const tab = TABS.find(t => t.key === key) || {name: key, icon: '📊'};

  // ── Collect real rows
  const realRows = d ? d.rows.filter(row => row.some(c => {
    const v = String(c ?? '').trim();
    return v && v !== '—' && v !== '-' && v !== 'null' && v !== 'N/A';
  })) : [];
  const total = realRows.length;

  // ── Name column stats
  const nameIdx = d ? d.headers.findIndex(h => isNameH(h)) : -1;
  const nameMap = {};
  if (nameIdx >= 0) {
    realRows.forEach(r => {
      const n = stripBrackets((r[nameIdx] || '').trim());
      if (n && n !== '—') nameMap[n] = (nameMap[n] || 0) + 1;
    });
  }
  const topNames = Object.entries(nameMap).sort((a,b) => b[1]-a[1]).slice(0, 5);
  const maxCount = topNames[0]?.[1] || 1;
  const uniqueNames = Object.keys(nameMap).length;

  // ── Date column stats
  const dateIdx = d ? d.headers.findIndex(h => isDateH(h)) : -1;
  let minDate = null, maxDate = null, dateCount = 0, monthMap = {};
  if (dateIdx >= 0) {
    realRows.forEach(r => {
      const v = (r[dateIdx] || '').trim();
      if (!v || v === '—') return;
      let dt = null;
      const dm = v.match(/^(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{2,4})$/);
      if (dm) {
        const yr = dm[3].length === 2 ? '20' + dm[3] : dm[3];
        dt = new Date(yr + '-' + dm[2].padStart(2,'0') + '-' + dm[1].padStart(2,'0'));
      } else dt = new Date(v);
      if (!dt || isNaN(dt)) return;
      dateCount++;
      if (!minDate || dt < minDate) minDate = dt;
      if (!maxDate || dt > maxDate) maxDate = dt;
      const mk = dt.toLocaleDateString('fr-FR', {month:'short', year:'2-digit'});
      monthMap[mk] = (monthMap[mk] || 0) + 1;
    });
  }
  const fmtDate = dt => dt ? capDate(dt.toLocaleDateString('fr-FR', {day:'2-digit', month:'short', year:'numeric'})) : '—';
  const daySpan = (minDate && maxDate) ? Math.round((maxDate - minDate) / 86400000) : null;

  // ── Build HTML
  const kpisHtml = `
    <div class="ksp-kpis">
      <div class="ksp-kpi">
        <div class="ksp-kpi-val">${total}</div>
        <div class="ksp-kpi-lbl">Total</div>
      </div>
      <div class="ksp-kpi">
        <div class="ksp-kpi-val">${uniqueNames || '—'}</div>
        <div class="ksp-kpi-lbl">Noms uniques</div>
      </div>
      <div class="ksp-kpi">
        <div class="ksp-kpi-val">${dateCount || '—'}</div>
        <div class="ksp-kpi-lbl">Dates</div>
      </div>
    </div>`;

  const namesHtml = topNames.length ? `
    <div class="ksp-section">
      <div class="ksp-section-title">Animateurs · Top ${topNames.length}</div>
      <div class="ksp-names">
        ${topNames.map(([n, c]) => `
          <div class="ksp-name-row">
            <span class="ksp-name-label">${esc(n)}</span>
            <div class="ksp-name-bar-wrap"><div class="ksp-name-bar" style="width:${Math.round(c/maxCount*100)}%"></div></div>
            <span class="ksp-name-count">${c}</span>
          </div>`).join('')}
      </div>
    </div>` : '';

  const datesHtml = (minDate || maxDate) ? `
    <div class="ksp-section">
      <div class="ksp-section-title">Période</div>
      <div class="ksp-dates">
        <div class="ksp-date-row"><span class="ksp-date-key">Première</span><span class="ksp-date-val">${fmtDate(minDate)}</span></div>
        <div class="ksp-date-row"><span class="ksp-date-key">Dernière</span><span class="ksp-date-val">${fmtDate(maxDate)}</span></div>
        ${daySpan !== null ? `<div class="ksp-date-row"><span class="ksp-date-key">Durée</span><span class="ksp-date-val">${daySpan} j</span></div>` : ''}
      </div>
    </div>` : '';

  const syncTime = new Date().toLocaleTimeString('fr-FR', {hour:'2-digit', minute:'2-digit'});

  panel.innerHTML = `
    <div class="ksp-head">
      <span class="ksp-icon">${tab.icon}</span>
      <span class="ksp-title">${esc(tab.name)}</span>
      <button class="ksp-close" onclick="closeStatPanel()">✕</button>
    </div>
    <div class="ksp-body">
      ${kpisHtml}
      ${namesHtml}
      ${datesHtml}
    </div>
    <div class="ksp-footer">Synchronisé à ${syncTime}</div>`;

  // ── Position near button
  const r = btn.getBoundingClientRect();
  const pw = 290;
  let left = r.left + r.width / 2 - pw / 2;
  let top = r.bottom + 10;
  left = Math.max(8, Math.min(left, window.innerWidth - pw - 8));
  if (top + 350 > window.innerHeight) top = r.top - 350;
  panel.style.left = left + 'px';
  panel.style.top = top + 'px';
  panel.classList.add('vis');

  // Auto-close on outside click
  clearTimeout(_kspTimer);
  _kspTimer = setTimeout(() => {
    document.addEventListener('click', _kspOutside, { once: true, capture: true });
  }, 50);
}

function _kspOutside(e) {
  const panel = document.getElementById('kstat-panel');
  if (panel && !panel.contains(e.target) && !e.target.classList.contains('ksp-stat-btn')) {
    closeStatPanel();
  }
}

function closeStatPanel() {
  const panel = document.getElementById('kstat-panel');
  if (panel) { panel.classList.remove('vis'); panel._activeKey = null; }
  document.removeEventListener('click', _kspOutside, true);
}

/* ════════════════════════════════════════
   ANIMATION CELL TOOLTIP
════════════════════════════════════════ */

let _katHideTimer = null;

/* Parse a date string → Date | null */
function parseDate(v) {
  if (!v || v === '—') return null;
  try {
    const dm = String(v).match(/^(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{2,4})$/);
    if (dm) {
      const yr = dm[3].length===2?'20'+dm[3]:dm[3];
      const dt = new Date(yr+'-'+dm[2].padStart(2,'0')+'-'+dm[1].padStart(2,'0'));
      return isNaN(dt) ? null : dt;
    }
    // ISO format yyyy-mm-dd
    const dt = new Date(v);
    return isNaN(dt) ? null : dt;
  } catch(e){ return null; }
}

function fmtShortDate(v) {
  const dt = parseDate(v);
  if (!dt) return v||'';
  return capDate(dt.toLocaleDateString('fr-FR',{day:'2-digit',month:'short',year:'numeric'}));
}

/* Capitalize month/weekday words in a formatted date string */
function capDate(s) {
  return String(s).replace(/\b([a-zàâéèêëîïôùûüç]{2,})\b/g, w => w.charAt(0).toUpperCase() + w.slice(1));
}

/* Map event name → color theme for the chip */
function animEventTheme(name) {
  const n = (name || '').toLowerCase();
  if (/quiz|quizz|question|culture/i.test(n))          return {bg:'rgba(136,68,255,.12)', border:'rgba(136,68,255,.3)', color:'#b090ff'};
  if (/pi.ge|mortel|trap|danger|survie/i.test(n))       return {bg:'rgba(255,60,60,.1)',   border:'rgba(255,60,60,.3)',   color:'#ff8080'};
  if (/cache|hide|seek/i.test(n))                       return {bg:'rgba(0,200,232,.09)',  border:'rgba(0,200,232,.28)',  color:'#60d8f0'};
  if (/rp\b|role.?play|classe|théâtre/i.test(n))        return {bg:'rgba(255,160,40,.1)',  border:'rgba(255,160,40,.3)', color:'#ffb860'};
  if (/course|race|sprint|vitesse/i.test(n))            return {bg:'rgba(40,220,120,.09)', border:'rgba(40,220,120,.3)', color:'#60e8a0'};
  if (/combat|battle|duel|fight|pvp/i.test(n))          return {bg:'rgba(255,80,40,.1)',   border:'rgba(255,80,40,.3)',  color:'#ff9070'};
  if (/tournoi|tournament/i.test(n))                    return {bg:'rgba(255,215,0,.09)',  border:'rgba(255,215,0,.28)', color:'#ffd700'};
  if (/chasse|hunt|boss|raid/i.test(n))                 return {bg:'rgba(255,120,200,.08)',border:'rgba(255,120,200,.25)',color:'#ff90d0'};
  return {bg:'rgba(255,255,255,.04)', border:'rgba(255,255,255,.1)', color:'var(--tx0)'};
}
function animEventIcon(name) {
  const n = (name || '').toLowerCase();
  if (/quiz|quizz|question|q&a|culture/i.test(n))           return '🧠';
  if (/pi.ge|mortel|trap|danger|survie|survival/i.test(n))  return '💀';
  if (/cache|hide|seek|cherche/i.test(n))                   return '🫥';
  if (/rp\b|role.?play|classe|théâtre|theater/i.test(n))   return '🎭';
  if (/course|race|sprint|vitesse|speed/i.test(n))          return '🏁';
  if (/combat|battle|duel|fight|pvp|war|guerre/i.test(n))   return '⚔️';
  if (/build|constru|création|create|craft/i.test(n))       return '🏗️';
  if (/chasse|hunt|boss|raid/i.test(n))                     return '🎯';
  if (/concert|music|chant|sing/i.test(n))                  return '🎵';
  if (/tournoi|tournament|compét/i.test(n))                 return '🏆';
  if (/vote|élect|sondage|poll/i.test(n))                   return '🗳️';
  if (/photo|screenshot|screen|image/i.test(n))             return '📸';
  if (/devin|riddle|énigme|enigme|mystère/i.test(n))        return '🔍';
  if (/carte|map|territoire|zone/i.test(n))                 return '🗺️';
  return '✦';
}
function findCol(headers, ...patterns) {
  return headers.findIndex(h =>
    patterns.some(p => typeof p === 'string'
      ? h.trim().toLowerCase().includes(p.toLowerCase())
      : p.test(h.trim())
    )
  );
}

function showAnimTip(e, personName) {
  const tip = document.getElementById('kanim-tip');
  if (!tip || !personName) return;
  clearTimeout(_katHideTimer);

  const entries = [];
  const d = D['suivis'];

  // Declare outside so debug block can access them
  let iDate=-1, iMembre=-1, iEvent=-1, iRecomp=-1, iPartic=-1, iGagnant=-1;

  if (d && d.headers && d.rows) {
    const H = d.headers;

    iDate    = findCol(H, 'date', 'horodateur', 'quand');
    iMembre  = findCol(H, 'membre', 'concerné', 'concern', 'pseudo', 'person');
    iEvent   = findCol(H, /nom.+v.+nement/i, /event/i, /nom event/i, "nom d'événement", "nom d'evenement", 'événement', 'evenement');
    iRecomp  = findCol(H, 'récompense', 'recompense', 'dotation', 'gain', 'grines', 'ogrine', 'prize', 'reward');
    iPartic  = findCol(H, 'participant', 'joueur', 'nb ', 'nombre');
    iGagnant = findCol(H, 'gagnant', 'winner', 'vainqueur');

    // Fallback: if iEvent not found, pick first col that's not date/membre/recomp/partic/gagnant/stat
    if (iEvent < 0) {
      const taken = new Set([iDate, iMembre, iRecomp, iPartic, iGagnant]);
      iEvent = H.findIndex((h, i) =>
        !taken.has(i) && h.trim().length > 0 &&
        !isStatH(h) && !isOgH(h) && !isUrlH(h) && !isAnimH(h)
      );
    }

    d.rows.forEach(row => {
      // Match by membre concerné — strip brackets for comparison
      const rawMembre = (row[iMembre] ?? '').toString().trim();
      const cleanMembre = stripBrackets(rawMembre).toLowerCase();
      if (!cleanMembre || cleanMembre !== personName.toLowerCase()) return;

      const get = i => i >= 0 ? (row[i] ?? '').toString().trim() : '';

      const rawDate  = get(iDate);
      const event    = get(iEvent);
      const recomp   = get(iRecomp);
      const partic   = get(iPartic);
      const gagnant  = get(iGagnant);

      // Skip rows with no event info
      if (!event && !recomp && !rawDate) return;

      entries.push({
        date    : rawDate  ? fmtShortDate(rawDate)  : '',
        event   : event    || '—',
        recomp  : recomp   || '',
        partic  : partic   || '',
        gagnant : gagnant  || '',
        _dt     : parseDate(rawDate)
      });
    });
  }

  // Sort by date desc
  entries.sort((a,b) => {
    if (!a._dt && !b._dt) return 0;
    if (!a._dt) return 1;
    if (!b._dt) return -1;
    return b._dt - a._dt;
  });

  const count  = entries.length;
  const initl  = (personName.split(/\s+/).map(w=>w[0]||'').join('').toUpperCase().slice(0,2))||'?';
  const photo  = PHOTOS[personName] || PHOTOS[stripBrackets(personName)];
  const avatarHtml = photo
    ? `<img src="${esc(photo)}" alt="${esc(initl)}">`
    : esc(initl);

  // ── Build entry cards
  const rowsHtml = count === 0
    ? `<div class="kat-empty">Aucune animation trouvée dans Suivis évent</div>`
    : entries.map(en => `
      <div class="kat-row">
        <div class="kat-icon">${animEventIcon(en.event)}</div>
        <div class="kat-info">
          <div class="kat-event">${esc(en.event)}</div>
          <div class="kat-meta">
            ${en.date    ? `<span class="kat-pill kat-pill-date">📅 ${esc(en.date)}</span>` : ''}
            ${en.recomp  ? `<span class="kat-pill kat-pill-pts">◈ ${esc(en.recomp)}</span>` : ''}
            ${en.partic  ? `<span class="kat-pill kat-pill-nb">× ${esc(en.partic)}</span>` : ''}
            ${en.gagnant ? `<span class="kat-pill kat-pill-ppl">🏆 ${esc(en.gagnant)}</span>` : ''}
          </div>
        </div>
      </div>`).join('');

  tip.innerHTML = `
    <div class="kat-head">
      <div class="kat-avatar">${avatarHtml}</div>
      <span class="kat-name">${esc(personName)}</span>
      <span class="kat-badge">${count}</span>
    </div>
    <div class="kat-body">${rowsHtml}</div>
    <div class="kat-footer">Source · Suivis évent · croisement live</div>`;

  // ── Position
  const tw = 380;
  const target = e.currentTarget || e.target;
  const r = target.getBoundingClientRect();
  let left = r.left + r.width/2 - tw/2;
  let top  = r.bottom + 10;
  left = Math.max(8, Math.min(left, window.innerWidth - tw - 8));
  const tipH = Math.min(440, 100 + count * 72);
  if (top + tipH > window.innerHeight) top = r.top - tipH - 6;
  tip.style.left  = left + 'px';
  tip.style.top   = top  + 'px';
  tip.style.width = tw   + 'px';
  tip.classList.add('vis');
}

function hideAnimTip() {
  const tip = document.getElementById('kanim-tip');
  if (!tip || tip._pinned) return; // ne pas fermer si épinglée
  _katHideTimer = setTimeout(() => {
    if (!tip._pinned) tip.classList.remove('vis');
  }, 120);
}

function pinAnimTip(e, personName) {
  e.stopPropagation();
  const tip = document.getElementById('kanim-tip');
  if (!tip) return;
  clearTimeout(_katHideTimer);

  // Si déjà épinglée sur ce même nom → fermer
  if (tip._pinned && tip._pinnedFor === personName) {
    closeAnimTip(); return;
  }

  // S'assurer que la bulle est affichée avec le bon contenu
  showAnimTip(e, personName);

  // Épingler
  tip._pinned = true;
  tip._pinnedFor = personName;
  tip.classList.add('pinned');
  tip.style.pointerEvents = 'auto';

  // Injecter le bouton ✕ dans le header si pas déjà présent
  const head = tip.querySelector('.kat-head');
  if (head && !head.querySelector('.kat-close')) {
    const btn = document.createElement('button');
    btn.className = 'kat-close';
    btn.innerHTML = '✕';
    btn.onclick = (ev) => { ev.stopPropagation(); closeAnimTip(); };
    head.appendChild(btn);
  }

  // Fermer au clic extérieur
  setTimeout(() => {
    document.addEventListener('click', _katOutside, { capture: true });
  }, 50);
}

function _katOutside(e) {
  const tip = document.getElementById('kanim-tip');
  if (tip && !tip.contains(e.target) && !e.target.classList.contains('anim-tip-cell')) {
    closeAnimTip();
  }
}

function closeAnimTip() {
  const tip = document.getElementById('kanim-tip');
  if (!tip) return;
  tip._pinned = false;
  tip._pinnedFor = null;
  tip.classList.remove('vis', 'pinned');
  tip.style.pointerEvents = 'none';
  const btn = tip.querySelector('.kat-close');
  if (btn) btn.remove();
  document.removeEventListener('click', _katOutside, true);
}

/* ════════════════════════════════════════
   CELL RENDERING
════════════════════════════════════════ */
function esc(s){return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function defaultAvatar(){return`<svg width="13" height="13" viewBox="0 0 24 24" fill="none"><circle cx="12" cy="8" r="4" fill="currentColor" opacity=".9"/><path d="M4 20c0-4 3.582-7 8-7s8 3 8 7" stroke="currentColor" stroke-width="2" stroke-linecap="round" fill="none" opacity=".7"/></svg>`;}
function stripBrackets(s){ return String(s||'').replace(/\s*\[.*?\]/g,'').trim(); }
function initials(s){const c=stripBrackets(s);return(c||'?').split(/\s+/).map(w=>w[0]||'').join('').toUpperCase().slice(0,2)||'?';}
function isNameH(h){return/pseudo|nom|prénom|name|membre|person|rempli/i.test(h);}
function isStatH(h){return/statut|status|état|présent|actif|validé|retour/i.test(h);}
function isDateH(h){return/date|début|fin|entrée|sortie|\bdu\b|\bau\b|quand|horodateur/i.test(h);}
function isOgH(h) {return/ogrine/i.test(h);}
function isUrlH(h) {return/lien|url|link/i.test(h);}
function isDiscordH(h){return/discord/i.test(h);}
function isIdH(h){return/^\s*id\s*$/i.test(h);}
function isNumH(h) {return/nombre|quantit|pts|points|total|montant|count/i.test(h);}
function isAnimH(h){return/^animation$/i.test(h.trim());}

const BADGES=[
  {rx:/^(actif|active)$/i,                                        cls:'bactive'},
  {rx:/^(oui|présent|validé|ok|accepté|confirmé)$/i,              cls:'bok'},
  {rx:/^(absent|non|inactif|refusé|terminé|fermé|désactivé)$/i,   cls:'binactive'},
  {rx:/^(en cours|en attente|pending)$/i,                        cls:'bwrn'},
  {rx:/^(planifié|prévu|upcoming|à venir)$/i,                    cls:'binf'},
  {rx:/^(admin|responsable|chef|leader|fondateur|propriétaire)$/i,cls:'bmg'},
  {rx:/^(animateur|anim\b|co-animateur)$/i,                      cls:'btl'},
  {rx:/^(modo|modérateur|moderateur)$/i,                         cls:'bgld'},
  {rx:/^(suspendu|banni|sanction|exclu)$/i,                      cls:'berr'},
];

function mkBadge(v){
  if(!v||v==='null') return '<span class="cd">—</span>';
  for(const r of BADGES) if(r.rx.test(v)) return `<span class="badge ${r.cls}">${esc(v)}</span>`;
  if(v.length<=24&&/^[\wÀ-ÿ\s\-\/]+$/.test(v)) return `<span class="badge bgr">${esc(v)}</span>`;
  return `<span class="ct">${esc(v)}</span>`;
}

function renderCell(v, h, personName){
  if(!v||v==='null') return '<span class="cd">—</span>';
  if(isAnimH(h)){
    const n = pn(v);
    const count = isNaN(n) ? 0 : n;
    if(count === 0) return `<span class="anim-zero" title="Aucun événement pour le moment">✕</span>`;
    const safeN = esc(personName||'');
    return `<span class="anim-tip-cell" data-anim-person="${safeN}" onmouseenter="showAnimTip(event,'${safeN.replace(/'/g,'\\&#39;')}')" onmouseleave="hideAnimTip()" onclick="pinAnimTip(event,'${safeN.replace(/'/g,'\\&#39;')}')" style="cursor:pointer">${count}</span>`;
  }
  if(isOgH(h)){const n=pn(v);return `<span class="cg" data-tip="Ogrines">${isNaN(n)?esc(v):fmt(n)+'\u00a0Ogrines'}</span>`;}
  if(isUrlH(h)){const href=/^https?:\/\//i.test(v)?v:'https://'+v;return `<a class="cl" href="${esc(href)}" target="_blank">Ouvrir ↗</a>`;}
  if(isDateH(h)){var dv=v;try{var dm=String(v).match(/^(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{2,4})$/);if(dm){var yr=dm[3].length===2?'20'+dm[3]:dm[3];var dt2=new Date(yr+'-'+dm[2].padStart(2,'0')+'-'+dm[1].padStart(2,'0'));if(!isNaN(dt2)&&dt2.getFullYear()>2000)dv=capDate(dt2.toLocaleDateString('fr-FR',{day:'2-digit',month:'long',year:'numeric'}));}else{var dt3=new Date(v);if(!isNaN(dt3)&&dt3.getFullYear()>2000)dv=capDate(dt3.toLocaleDateString('fr-FR',{day:'2-digit',month:'long',year:'numeric'}));}}catch(e){}return `<span class="date-cell-w"><svg class="date-cal-ic" style="vertical-align:middle;margin-right:6px;position:relative;top:-2px" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="3" y="4" width="18" height="17" rx="3" stroke="currentColor" stroke-width="1.6"/><path d="M3 9h18" stroke="currentColor" stroke-width="1.6"/><path d="M8 2v4M16 2v4" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/><circle cx="12" cy="15" r="1.2" fill="currentColor" class="date-cal-dot"/></svg><span class="cm" style="vertical-align:middle">${esc(dv)}</span></span>`;}
  if(isStatH(h)) return mkBadge(v);
  if(isNumH(h)){const n=pn(v);return `<span class="cm">${isNaN(n)?esc(v):fmt(n)}</span>`;}
  if(isIdH(h)){const n=parseInt(v,10);return `<span class="cid">#${isNaN(n)?esc(v):n}</span>`;}
  if(isDiscordH(h)){return `<span class="disc-w"><span class="disc-ic-wrap"><svg class="disc-ic" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path d="M20.317 4.37a19.791 19.791 0 0 0-4.885-1.515.074.074 0 0 0-.079.037c-.21.375-.444.864-.608 1.25a18.27 18.27 0 0 0-5.487 0 12.64 12.64 0 0 0-.617-1.25.077.077 0 0 0-.079-.037A19.736 19.736 0 0 0 3.677 4.37a.07.07 0 0 0-.032.027C.533 9.046-.32 13.58.099 18.057c.002.022.015.043.03.056a19.9 19.9 0 0 0 5.993 3.03.078.078 0 0 0 .084-.028 14.09 14.09 0 0 0 1.226-1.994.076.076 0 0 0-.041-.106 13.107 13.107 0 0 1-1.872-.892.077.077 0 0 1-.008-.128 10.2 10.2 0 0 0 .372-.292.074.074 0 0 1 .077-.01c3.928 1.793 8.18 1.793 12.062 0a.074.074 0 0 1 .078.01c.12.098.246.198.373.292a.077.077 0 0 1-.006.127 12.299 12.299 0 0 1-1.873.892.077.077 0 0 0-.041.107c.36.698.772 1.362 1.225 1.993a.076.076 0 0 0 .084.028 19.839 19.839 0 0 0 6.002-3.03.077.077 0 0 0 .032-.054c.5-5.177-.838-9.674-3.549-13.66a.061.061 0 0 0-.031-.03zM8.02 15.33c-1.183 0-2.157-1.085-2.157-2.419 0-1.333.956-2.419 2.157-2.419 1.21 0 2.176 1.096 2.157 2.42 0 1.333-.956 2.418-2.157 2.418zm7.975 0c-1.183 0-2.157-1.085-2.157-2.419 0-1.333.955-2.419 2.157-2.419 1.21 0 2.176 1.096 2.157 2.42 0 1.333-.946 2.418-2.157 2.418z" fill="#5865F2"/></svg></span><span class="disc-tag">${esc(v)}</span></span>`;}
  return `<span class="ct">${esc(v)}</span>`;
}

/* ════════════════════════════════════════
   RENDER DISPATCH
════════════════════════════════════════ */
function renderCur(){
  if(cur==='dashboard'){updateStats();renderDash();}
  else if(cur==='analytics') renderAnalytics();
  else if(cur==='activity')  renderActivity();
  else if(cur==='archives')  renderArchives();
  else renderTab(cur);
}

/* ════════════════════════════════════════
   NAVIGATION
════════════════════════════════════════ */
function setCurrentTitle(label){
  const el=document.getElementById('bc-cur');
  if(!el) return;
  const txt=String(label||'').trim();
  el.setAttribute('aria-label', txt);
  el.innerHTML=[...txt].map((ch,i)=>`<span class="dash-letter${ch===' ' ? ' space' : ''}" style="--i:${i}">${ch===' ' ? '&nbsp;' : esc(ch)}</span>`).join('');
}

function goTo(key){
  // Forcer display:none sur TOUTES les vues d'abord
  document.querySelectorAll('.view').forEach(v => {
    v.classList.remove('active');
    v.style.display = 'none';
  });
  document.querySelectorAll('.ni').forEach(n=>n.classList.remove('active'));
  
  // Activer uniquement la vue cible
  const targetView = document.getElementById('view-'+key);
  if (targetView) {
    targetView.classList.add('active');
    targetView.style.display = 'block';
  }
  
  document.getElementById('ni-'+key)?.classList.add('active');
  setCurrentTitle(NAV[key]||key.toUpperCase());
  cur=key; renderCur();
  
  // Remettre le scroll en haut quand on change de page
  const contentEl = document.querySelector('.content');
  if (contentEl) contentEl.scrollTop = 0;
  
  // Masquer le bouton de retour uniquement sur dashboard/analytics/activity
  const backBtn = document.getElementById('back-to-dash-btn');
  if (backBtn) {
    if (key === 'dashboard' || key === 'analytics' || key === 'activity') {
      backBtn.classList.add('hide');
    } else {
      backBtn.classList.remove('hide');
    }
  }
}

/* ════════════════════════════════════════
   UI HELPERS
════════════════════════════════════════ */
function setDot(t,txt){
  document.getElementById('sdot').className='sdot '+t;
  document.getElementById('stext').textContent=txt;
}
function showErr(v){document.getElementById('errbox').classList.toggle('show',v);}
function empty(icon,msg,sub=''){return `<div class="empty"><span class="ei">${icon}</span>${esc(msg)}<div class="es">${esc(sub)}</div></div>`;}

const TOAST_COLORS={'live':'rgba(34,204,122,.08)','og':'rgba(240,184,48,.08)','warn':'rgba(240,48,80,.08)'};
function toast(icon,msg,type=''){
  const tray=document.getElementById('tray');
  const el=document.createElement('div');
  el.className='toast'+(type==='live'?' toast-live':type==='og'?' toast-og':'');
  el.innerHTML=`<span>${icon}</span>${esc(msg)}`;
  tray.appendChild(el);
  setTimeout(()=>el.remove(),4200);
}

function showUpd(name, n){
  const el=document.getElementById('upd');
  el.textContent=`✦ ${n} nouvelle${n>1?'s':''} entrée${n>1?'s':''} dans ${name}`;
  el.classList.add('show');
  setTimeout(()=>el.classList.remove('show'),4000);
}

