document.getElementById('logo-btn').addEventListener('click',()=>document.getElementById('logo-file').click());
document.getElementById('logo-file').addEventListener('change',function(){
  const f=this.files[0];if(!f)return;
  const r=new FileReader();
  r.onload=e=>{
    document.getElementById('logo-img').src=e.target.result;
    document.getElementById('logo-img').style.display='block';
    document.getElementById('logo-ph').style.display='none';
    try{localStorage.setItem('karashi_logo',e.target.result);}catch(_){}
    toast('🖼','Logo mis à jour');
  };
  r.readAsDataURL(f);
});
